using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Observer.Linear;

internal sealed class GainRayNuisanceDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Trace-kernel nuisance geometry for mixed words", H("Trace-kernel nuisance geometry for mixed words"), Blocks(
            Describe.Lean(DescribeId.Create("gain-ray-nuisance-scalar-kernel-source"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayNuisance.scalar_kernel_source"),
                H("A common source in the actual scalar kernel"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every natural d, chronological Boolean word w and fixed Readout d w C whose scalarFunctional is nonzero, scalarRepresentative is nonzero and represents that functional by the trace pairing on every real auxiliary matrix. There is one auxiliary S in its kernel such that, simultaneously at every original prefix i in Fin(length(w)+1), trace(acquisition(take i w)*S) is zero if and only if that cumulative matrix is a real scalar multiple of scalarRepresentative. The representative is the weighted sum of the actual cumulative matrices with weights C(0,i). Trace-pairing extensionality identifies the vanishing restrictions, and finite hyperplane avoidance supplies the simultaneous S. Auxiliary matrices here have no physical positivity requirement."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-nuisance-weighted-evaluation-rank"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayNuisance.weighted_evaluation_rank"),
                H("The exact rank with arbitrary vanishing weights"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every natural d,n, injective real nodes t indexed by Fin n, and arbitrary real weights a indexed by Fin n, the matrix with entries a(i)*t(i)^k for k in Fin(d+1) has rank min(number of nonzero weights,d+1). The zero-support and rank-deficient cases are included. Select that many nonzero rows. Distinct-node interpolation, followed by division by the selected nonzero weights, makes the restricted evaluation onto. The number of supported rows and the whole coefficient dimension give the matching upper bounds."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-nuisance-scalar-kernel-endpoint"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayNuisance.scalar_kernel_endpoint"),
                H("The exact twice-dimension kernel equality"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every natural d, word w, fixed C, and nonzero real linear functional ell on the full auxiliary matrix space, suppose response(T)=ell(T)*I for every auxiliary T and length(w)+1 is at most 2(d+1). If S belongs to ker ell and every actual cumulative trace at S is nonzero, then length(w)+1 equals 2(d+1) and ker C is exactly the image of responseMatrix(S). A nonzero scalar response makes C onto. The weighted evaluation image has dimension d+1 and lies in its kernel, so rank-nullity forces both equalities."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-nuisance-scalar-kernel-ratios"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayNuisance.scalar_kernel_ratios"),
                H("Every endpoint ratio diagonal is scalar"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Under the endpoint hypotheses with d at least one, for every T in ker ell and every two original prefix indices i,j, the ratios trace(A_i*T)/trace(A_i*S) and trace(A_j*T)/trace(A_j*S) coincide. Indeed, kernel equality shows that multiplying any degree-at-most-d evaluation vector by these ratios again gives such an evaluation vector. Diagonal evaluation rigidity then applies, including when one or every numerator vanishes. No invertibility of the ratio diagonal is assumed."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-nuisance-scalar-kernel-span-le-two"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayNuisance.scalar_kernel_span_le_two"),
                H("The actual cumulative matrix span has dimension at most two"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every d at least one, word w and C with nonzero scalarFunctional, the universal scalar response identity and a scalar-kernel S with every cumulative trace nonzero imply that the span of all initial-inclusive cumulative matrices has dimension at most two when the read count is at most 2(d+1). The ratio law makes each trace functional, restricted to the scalar kernel, proportional to the initial trace functional. Subtracting that multiple gives a functional vanishing on the scalar kernel, hence a multiple of the scalarFunctional itself. Trace-pairing extensionality places each actual matrix in the span of the initial matrix and scalarRepresentative."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-nuisance-mixed-scalar-obstruction"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayNuisance.mixed_scalar_obstruction"),
                H("Every mixed word is obstructed through 2(d+1) reads"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every d at least one and every chronological Boolean word w containing both M=false and J=true, with initial-inclusive read count at most 2(d+1), any fixed C which annihilates the constant drift and satisfies response(T)=scalarFunctional(T)*I for every auxiliary real matrix T has scalarFunctional equal to zero. Choose a scalar-kernel S realizing precisely the proportionality-class zeros. If there is a zero trace, the nuisance image misses the all-ones drift vector, and its exact rank and the bound on the proportionality-class size contradict rank-nullity. If there are no zero traces, the endpoint argument bounds the cumulative span by two, whereas every mixed word has span at least three. Both switch orientations and every first-switch location are included."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-nuisance-mixed-chart-success-certificate"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayNuisance.mixed_chart_success_certificate"),
                H("An actual success supplies a nonzero chart certificate"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every d at least one, every mixed word with at most 2(d+1) initial-inclusive reads, every fixed C and every native world W where C succeeds with a nonzero scale of either sign, there are coefficient indices j,k such that chartWedge(C,j,k) is a nonzero polynomial. At every legal positive chart point, every actual success of that same C lies in its zero set; the polynomial is nonzero almost everywhere in the ambient real chart coordinate space. If all wedges vanished identically, whole-domain collinearity would give the scalar identity and the actual success would force its scalarFunctional to be nonzero, contrary to the mixed obstruction. This ambient certificate makes no assertion about nonvanishing after substitution on a prescribed-history fiber."))), DescribeRole.Theorem))));
}
